import path from 'node:path';

import { CONFIG_ENV_VARS, DEFAULT_CONFIG, loadConfig } from './config.js';
import { ERROR_CODES, EXIT_CODES, TodoError, UsageError } from './errors.js';
import { DEFAULT_ID_STRATEGY } from './id-strategies.js';
import { EMPTY_LIST_MESSAGE, formatTodoList, sanitizeForTerminal } from './format.js';
import { readTodoState, TODO_FILE_NAME, updateTodoState } from './storage.js';
import { addTodo, completeTodos, deleteTodos, normalizeTodoText, parseTodoId } from './todos.js';

/** How the program is invoked, as shown in help and error messages. */
export const PROGRAM_NAME = 'node index.js';

const HELP_WORDS = new Set(['help', '--help', '-h']);
const HELP_GUTTER = 2;

/**
 * @typedef {object} CommandContext
 * @property {string} filePath Absolute path of todos.json.
 * @property {import('./config.js').Config} config
 * @property {() => Date} now
 */

function storageOptions(config) {
  return { idStrategy: config.idStrategy, lockTimeoutMs: config.lockTimeoutMs };
}

function parseIds(args, usage) {
  if (args.length === 0) throw new UsageError('Missing todo id', { usage });
  return args.map((arg) => parseTodoId(arg));
}

function describeTodo(todo) {
  return `todo #${todo.id}: ${sanitizeForTerminal(todo.text)}`;
}

/** @param {string[]} args @param {CommandContext} context */
async function addCommand(args, { filePath, config, now }) {
  if (args.length === 0) throw new UsageError('Missing todo text', { usage: COMMANDS.add.usage });
  // Validate before taking the lock so bad input is reported at once, not after waiting for another command.
  const text = normalizeTodoText(args.join(' '), config);
  const { todo } = await updateTodoState(
    filePath,
    (state, idStrategy) =>
      addTodo(state, text, {
        idStrategy,
        now: now(),
        maxTextLength: config.maxTextLength,
        maxItems: config.maxItems,
      }),
    storageOptions(config),
  );
  return `Added ${describeTodo(todo)}`;
}

/** @param {string[]} args @param {CommandContext} context */
async function listCommand(args, { filePath }) {
  if (args.length > 0) throw new UsageError('"list" does not take arguments', { usage: COMMANDS.list.usage });
  const { todos } = await readTodoState(filePath);
  if (todos.length === 0) return `${EMPTY_LIST_MESSAGE} Add one with: ${PROGRAM_NAME} add "Buy groceries"`;
  return formatTodoList(todos);
}

/** @param {string[]} args @param {CommandContext} context */
async function completeCommand(args, { filePath, config }) {
  const ids = parseIds(args, COMMANDS.complete.usage);
  const { results } = await updateTodoState(filePath, (state) => completeTodos(state, ids), storageOptions(config));
  return results
    .map(({ todo, alreadyCompleted }) => `${alreadyCompleted ? 'Already completed' : 'Completed'} ${describeTodo(todo)}`)
    .join('\n');
}

/** @param {string[]} args @param {CommandContext} context */
async function deleteCommand(args, { filePath, config }) {
  const ids = parseIds(args, COMMANDS.delete.usage);
  const { deleted } = await updateTodoState(filePath, (state) => deleteTodos(state, ids), storageOptions(config));
  return deleted.map((todo) => `Deleted ${describeTodo(todo)}`).join('\n');
}

const COMMANDS = Object.freeze({
  add: { usage: 'add <text>', summary: 'Add a todo. Quote the text, or pass it as several words.', run: addCommand },
  list: { usage: 'list', summary: 'Show every todo: id, [x] done or [ ] pending, and text.', run: listCommand },
  complete: { usage: 'complete <id> [<id>...]', summary: 'Mark one or more todos as done.', run: completeCommand },
  delete: { usage: 'delete <id> [<id>...]', summary: 'Remove one or more todos.', run: deleteCommand },
});

const COMMAND_HELP_ROWS = [
  ...Object.values(COMMANDS).map(({ usage, summary }) => [usage, summary]),
  ['help', 'Show this help.'],
];
const ENVIRONMENT_HELP_ROWS = [
  [
    `${CONFIG_ENV_VARS.idStrategy}=max|sequence`,
    `How ids are assigned; sequence never reuses ids. If unset, a list keeps its current one (new lists: ${DEFAULT_ID_STRATEGY})`,
  ],
  [`${CONFIG_ENV_VARS.maxTextLength}=<n>`, `Longest todo text accepted (default ${DEFAULT_CONFIG.maxTextLength})`],
  [`${CONFIG_ENV_VARS.maxItems}=<n>`, `Most todos a list may hold (default ${DEFAULT_CONFIG.maxItems})`],
  [`${CONFIG_ENV_VARS.lockTimeoutMs}=<n>`, `Milliseconds to wait for another running command (default ${DEFAULT_CONFIG.lockTimeoutMs})`],
];
const HELP_COLUMN_WIDTH =
  Math.max(...[...COMMAND_HELP_ROWS, ...ENVIRONMENT_HELP_ROWS].map(([left]) => left.length)) + HELP_GUTTER;
const helpLine = ([left, right]) => `  ${left.padEnd(HELP_COLUMN_WIDTH)}${right}`;

/** Text printed by `help`, `--help` and `-h`. */
export const HELP_TEXT = [
  `Usage: ${PROGRAM_NAME} <command> [arguments]`,
  '',
  'Commands:',
  ...COMMAND_HELP_ROWS.map(helpLine),
  '',
  `Todos are saved in ./${TODO_FILE_NAME}. Optional environment variables:`,
  ...ENVIRONMENT_HELP_ROWS.map(helpLine),
].join('\n');

function currentDirectory() {
  try {
    return process.cwd();
  } catch (error) {
    throw new TodoError(`Could not determine the current directory (was it deleted?): ${error.message}`, {
      code: ERROR_CODES.storage,
      cause: error,
    });
  }
}

async function dispatch(argv, { cwd, env, now }) {
  const [name, ...args] = argv;
  if (name === undefined) throw new UsageError('Missing command', { usage: '<command> [arguments]' });
  if (HELP_WORDS.has(name)) return HELP_TEXT;
  if (!Object.hasOwn(COMMANDS, name)) throw new UsageError(`Unknown command ${JSON.stringify(name)}`);
  const context = { filePath: path.join(cwd ?? currentDirectory(), TODO_FILE_NAME), config: loadConfig(env), now };
  return COMMANDS[name].run(args, context);
}

// Error messages can quote todos.json content (JSON.parse snippets, field
// values) and argv, so they are escaped like todo text before printing.
function describeFailure(error) {
  if (!(error instanceof TodoError)) {
    const detail = error instanceof Error ? error.stack : String(error);
    return `Unexpected error: ${detail}`.split('\n').map(sanitizeForTerminal).join('\n');
  }
  const lines = [`Error: ${sanitizeForTerminal(error.message)}`];
  if (error instanceof UsageError) {
    if (error.usage !== undefined) lines.push(`Usage: ${PROGRAM_NAME} ${error.usage}`);
    lines.push(`Run "${PROGRAM_NAME} help" to see all commands.`);
  } else if (error.code === ERROR_CODES.notFound) {
    lines.push(`Run "${PROGRAM_NAME} list" to see the ids in use.`);
  }
  return lines.join('\n');
}

/**
 * Runs one CLI invocation against `<cwd>/todos.json`. Never rejects: results
 * go to `stdout`, failures to `stderr`, and the outcome is the exit code.
 * @param {readonly string[]} argv Arguments after `node index.js`.
 * @param {{
 *   cwd?: string, Defaults to process.cwd(), read only for commands that use todos.json.
 *   env?: Record<string, string | undefined>,
 *   stdout?: { write(chunk: string): unknown },
 *   stderr?: { write(chunk: string): unknown },
 *   now?: () => Date,
 * }} [io]
 * @returns {Promise<number>} One of EXIT_CODES.
 */
export async function run(argv, io = {}) {
  const {
    cwd,
    env = process.env,
    stdout = process.stdout,
    stderr = process.stderr,
    now = () => new Date(),
  } = io;
  try {
    stdout.write(`${await dispatch(argv, { cwd, env, now })}\n`);
    return EXIT_CODES.success;
  } catch (error) {
    stderr.write(`${describeFailure(error)}\n`);
    return error instanceof TodoError ? error.exitCode : EXIT_CODES.failure;
  }
}
// Pure todo-list operations. Nothing here touches the filesystem or the clock;
// every mutation returns a new state and leaves its input untouched.
import { ERROR_CODES, TodoError, UsageError } from './errors.js';

/**
 * @typedef {object} Todo
 * @property {number} id Positive integer, unique within the list.
 * @property {string} text
 * @property {boolean} completed
 * @property {string} createdAt ISO 8601 timestamp.
 */

/**
 * @typedef {object} TodoState
 * @property {readonly Todo[]} todos
 * @property {number} lastId Highest id ever assigned. Only the `sequence` id strategy persists it.
 * @property {boolean} [storesLastId] Whether todos.json was saved in the `{ lastId, todos }` layout.
 */

const CONTROL_CHARACTER = /\p{Cc}/u;
// The limit counts user-perceived characters, and one of those can carry any
// number of combining marks. Capping code points too keeps the limit a bound on
// stored size. 16 leaves room for the longest emoji sequences (11 code points).
const MAX_CODE_POINTS_PER_CHARACTER = 16;
const DIGITS_ONLY = /^\d+$/;
const graphemeSegmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });

/**
 * Counts user-perceived characters, so an emoji with a skin tone or a letter
 * with a combining accent counts as one.
 * @param {string} text
 */
export function countGraphemes(text) {
  return Array.from(graphemeSegmenter.segment(text)).length;
}

/**
 * Validates todo text from the user and returns the form to store:
 * NFC-normalized and trimmed.
 * @param {string} rawText
 * @param {{ maxTextLength: number }} limits
 * @throws {UsageError} INVALID_ARGUMENT when the text is empty, multi-line or too long.
 */
export function normalizeTodoText(rawText, { maxTextLength }) {
  const text = rawText.normalize('NFC').trim();
  if (text === '') {
    throw new UsageError('Todo text cannot be empty', { code: ERROR_CODES.invalidArgument });
  }
  // Control characters would break the one-line-per-todo list output, and
  // escape sequences could rewrite the user's terminal when listed.
  if (CONTROL_CHARACTER.test(text)) {
    throw new UsageError('Todo text must be a single line without control characters (newlines, tabs, escape codes)', {
      code: ERROR_CODES.invalidArgument,
    });
  }
  const codePoints = Array.from(text).length;
  const maxCodePoints = maxTextLength * MAX_CODE_POINTS_PER_CHARACTER;
  if (codePoints > maxCodePoints) {
    throw new UsageError(`Todo text is too long: ${codePoints} code points, maximum is ${maxCodePoints}`, {
      code: ERROR_CODES.invalidArgument,
    });
  }
  const length = countGraphemes(text);
  if (length > maxTextLength) {
    throw new UsageError(`Todo text is too long: ${length} characters, maximum is ${maxTextLength}`, {
      code: ERROR_CODES.invalidArgument,
    });
  }
  return text;
}

/**
 * Parses a todo id typed by the user. Only ASCII digits are accepted, so
 * `1e3`, `0x10`, `+1` and `1.5` are rejected rather than coerced.
 * @param {string} raw
 * @throws {UsageError} INVALID_ARGUMENT when the value is not a positive safe integer.
 */
export function parseTodoId(raw) {
  const value = raw.trim();
  const id = DIGITS_ONLY.test(value) ? Number(value) : Number.NaN;
  if (!Number.isSafeInteger(id) || id < 1) {
    throw new UsageError(`Invalid todo id ${JSON.stringify(raw)}: expected a positive whole number such as 1`, {
      code: ERROR_CODES.invalidArgument,
    });
  }
  return id;
}

/**
 * Appends a new pending todo.
 * @param {TodoState} state
 * @param {string} rawText
 * @param {{ idStrategy: import('./id-strategies.js').IdStrategy, now: Date, maxTextLength: number, maxItems: number }} options
 * @returns {{ state: TodoState, todo: Todo, changed: true }}
 */
export function addTodo(state, rawText, { idStrategy, now, maxTextLength, maxItems }) {
  const text = normalizeTodoText(rawText, { maxTextLength });
  if (state.todos.length >= maxItems) {
    throw new TodoError(`Cannot add todo: the list already holds the maximum of ${maxItems} todos. Delete some first.`, {
      code: ERROR_CODES.limitExceeded,
    });
  }
  const id = idStrategy.nextId(state);
  const todo = { id, text, completed: false, createdAt: now.toISOString() };
  return { state: { ...state, todos: [...state.todos, todo], lastId: id }, todo, changed: true };
}

/**
 * Resolves ids to todos in argument order, dropping duplicates. Throws before
 * any change is made if an id is unknown, so multi-id commands are all-or-nothing.
 */
function findAll(todos, ids) {
  const byId = new Map(todos.map((todo) => [todo.id, todo]));
  const uniqueIds = [...new Set(ids)];
  const missing = uniqueIds.filter((id) => !byId.has(id));
  if (missing.length > 0) {
    const listed = missing.map((id) => `#${id}`).join(', ');
    const subject = missing.length === 1 ? `No todo with id ${listed}` : `No todos with ids ${listed}`;
    const detail = todos.length === 0 ? ' (the list is empty)' : '';
    throw new TodoError(`${subject}${detail}`, { code: ERROR_CODES.notFound });
  }
  return uniqueIds.map((id) => byId.get(id));
}

/**
 * Marks todos as completed. Completing a todo that is already done is not an error.
 * @param {TodoState} state
 * @param {readonly number[]} ids
 * @returns {{ state: TodoState, results: { todo: Todo, alreadyCompleted: boolean }[], changed: boolean }}
 * @throws {TodoError} NOT_FOUND when any id is unknown; nothing is completed in that case.
 */
export function completeTodos(state, ids) {
  const results = findAll(state.todos, ids).map((todo) =>
    todo.completed ? { todo, alreadyCompleted: true } : { todo: { ...todo, completed: true }, alreadyCompleted: false },
  );
  const updates = new Map(results.filter((result) => !result.alreadyCompleted).map(({ todo }) => [todo.id, todo]));
  const todos = state.todos.map((todo) => updates.get(todo.id) ?? todo);
  return { state: { ...state, todos }, results, changed: updates.size > 0 };
}

/**
 * Removes todos. `lastId` is kept so the `sequence` strategy never reissues a deleted id.
 * @param {TodoState} state
 * @param {readonly number[]} ids
 * @returns {{ state: TodoState, deleted: Todo[], changed: boolean }}
 * @throws {TodoError} NOT_FOUND when any id is unknown; nothing is deleted in that case.
 */
export function deleteTodos(state, ids) {
  const deleted = findAll(state.todos, ids);
  const doomed = new Set(deleted.map((todo) => todo.id));
  const todos = state.todos.filter((todo) => !doomed.has(todo.id));
  return { state: { ...state, todos }, deleted, changed: deleted.length > 0 };
}
/** Process exit codes returned by the CLI. */
export const EXIT_CODES = Object.freeze({
  success: 0,
  failure: 1,
  usage: 2,
});

/** Stable identifiers for expected failures, so callers and tests never match on message text. */
export const ERROR_CODES = Object.freeze({
  usage: 'USAGE',
  invalidArgument: 'INVALID_ARGUMENT',
  invalidConfig: 'INVALID_CONFIG',
  notFound: 'NOT_FOUND',
  limitExceeded: 'LIMIT_EXCEEDED',
  corruptFile: 'CORRUPT_FILE',
  storage: 'STORAGE',
  lockTimeout: 'LOCK_TIMEOUT',
  lockLost: 'LOCK_LOST',
});

/**
 * An expected failure whose message is safe to show the user as-is.
 * Anything thrown that is not a TodoError is treated as a bug.
 */
export class TodoError extends Error {
  /**
   * @param {string} message
   * @param {{ code?: string, exitCode?: number, cause?: unknown }} [options]
   */
  constructor(message, { code = ERROR_CODES.storage, exitCode = EXIT_CODES.failure, cause } = {}) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = new.target.name;
    this.code = code;
    this.exitCode = exitCode;
  }
}

/** The command line or environment was invalid; the CLI exits with EXIT_CODES.usage. */
export class UsageError extends TodoError {
  /**
   * @param {string} message
   * @param {{ code?: string, usage?: string, cause?: unknown }} [options]
   *   `usage` is the synopsis of the command that was misused, e.g. `complete <id>...`.
   */
  constructor(message, { code = ERROR_CODES.usage, usage, cause } = {}) {
    super(message, { code, exitCode: EXIT_CODES.usage, cause });
    this.usage = usage;
  }
}
/** Status indicators shown by `list`. */
export const STATUS_MARKERS = Object.freeze({ done: '[x]', pending: '[ ]' });

/** Printed by `list` when there is nothing to show. */
export const EMPTY_LIST_MESSAGE = 'No todos yet.';

const CONTROL_CHARACTERS = /\p{Cc}/gu;
const UNICODE_ESCAPE_WIDTH = 4;

/**
 * Shows control characters as `\uXXXX`. The CLI rejects them on input, but a
 * hand-edited or shared todos.json could still carry escape sequences that
 * would otherwise be interpreted by the terminal.
 * @param {string} text
 */
export function sanitizeForTerminal(text) {
  return text.replace(
    CONTROL_CHARACTERS,
    (character) => `\\u${character.codePointAt(0).toString(16).padStart(UNICODE_ESCAPE_WIDTH, '0')}`,
  );
}

/**
 * One `list` line, e.g. `3. [x] Buy groceries`.
 * @param {import('./todos.js').Todo} todo
 * @param {number} [idWidth] Pad the id to this many columns so markers line up.
 */
export function formatTodoLine(todo, idWidth = String(todo.id).length) {
  const marker = todo.completed ? STATUS_MARKERS.done : STATUS_MARKERS.pending;
  return `${String(todo.id).padStart(idWidth)}. ${marker} ${sanitizeForTerminal(todo.text)}`;
}

/**
 * e.g. `3 todos: 2 pending, 1 done`.
 * @param {readonly import('./todos.js').Todo[]} todos
 */
export function formatSummary(todos) {
  const done = todos.filter((todo) => todo.completed).length;
  const noun = todos.length === 1 ? 'todo' : 'todos';
  return `${todos.length} ${noun}: ${todos.length - done} pending, ${done} done`;
}

/**
 * The full `list` output: todos in id order followed by a summary line.
 * @param {readonly import('./todos.js').Todo[]} todos
 */
export function formatTodoList(todos) {
  if (todos.length === 0) return EMPTY_LIST_MESSAGE;
  const sorted = todos.toSorted((a, b) => a.id - b.id);
  const idWidth = String(sorted.at(-1).id).length;
  return [...sorted.map((todo) => formatTodoLine(todo, idWidth)), '', formatSummary(todos)].join('\n');
}
import { ERROR_CODES, UsageError } from './errors.js';
import { ID_STRATEGIES } from './id-strategies.js';

/** Environment variable that controls each setting. */
export const CONFIG_ENV_VARS = Object.freeze({
  idStrategy: 'TODO_ID_STRATEGY',
  maxTextLength: 'TODO_MAX_TEXT_LENGTH',
  maxItems: 'TODO_MAX_ITEMS',
  lockTimeoutMs: 'TODO_LOCK_TIMEOUT_MS',
});

/**
 * Values used when a variable is unset or blank. TODO_ID_STRATEGY has no
 * default here: unset, each list keeps the strategy it was saved with.
 */
export const DEFAULT_CONFIG = Object.freeze({
  maxTextLength: 500,
  maxItems: 10_000,
  lockTimeoutMs: 5_000,
});

const DIGITS_ONLY = /^\d+$/;

/**
 * @typedef {object} Config
 * @property {import('./id-strategies.js').IdStrategy | undefined} idStrategy Undefined when not set explicitly.
 * @property {number} maxTextLength Longest todo text accepted, in user-perceived characters.
 * @property {number} maxItems Most todos a list may hold.
 * @property {number} lockTimeoutMs How long a command waits for another one to release todos.json.
 */

function readSetting(env, key) {
  const value = env[CONFIG_ENV_VARS[key]]?.trim();
  return value === undefined || value === '' ? undefined : value;
}

function invalid(key, env, expected) {
  const name = CONFIG_ENV_VARS[key];
  return new UsageError(`Invalid ${name}=${JSON.stringify(env[name])}: expected ${expected}`, {
    code: ERROR_CODES.invalidConfig,
  });
}

function readInteger(env, key, minimum) {
  const value = readSetting(env, key);
  if (value === undefined) return DEFAULT_CONFIG[key];
  const number = DIGITS_ONLY.test(value) ? Number(value) : Number.NaN;
  if (!Number.isSafeInteger(number) || number < minimum) {
    throw invalid(key, env, `a whole number of at least ${minimum}`);
  }
  return number;
}

function readIdStrategy(env) {
  const value = readSetting(env, 'idStrategy');
  if (value === undefined) return undefined;
  const name = value.toLowerCase();
  if (!Object.hasOwn(ID_STRATEGIES, name)) {
    throw invalid('idStrategy', env, `one of ${Object.keys(ID_STRATEGIES).join(', ')}`);
  }
  return ID_STRATEGIES[name];
}

/**
 * Builds the configuration from environment variables (see CONFIG_ENV_VARS).
 * @param {Record<string, string | undefined>} env
 * @returns {Readonly<Config>}
 * @throws {UsageError} INVALID_CONFIG naming the offending variable.
 */
export function loadConfig(env) {
  return Object.freeze({
    idStrategy: readIdStrategy(env),
    maxTextLength: readInteger(env, 'maxTextLength', 1),
    maxItems: readInteger(env, 'maxItems', 1),
    lockTimeoutMs: readInteger(env, 'lockTimeoutMs', 0),
  });
}
# cli-todo-app

A command-line todo list for Node.js. Todos are stored in `todos.json` in the directory you run the command from. There are no runtime dependencies.

## Requirements

Node.js 22 or later.

## Usage

```console
$ node index.js add "Buy groceries"
Added todo #1: Buy groceries

$ node index.js add Walk the dog          # quotes are optional
Added todo #2: Walk the dog

$ node index.js complete 2
Completed todo #2: Walk the dog

$ node index.js list
1. [ ] Buy groceries
2. [x] Walk the dog

2 todos: 1 pending, 1 done

$ node index.js delete 1
Deleted todo #1: Buy groceries
```

| Command | What it does |
| --- | --- |
| `add <text>` | Adds a pending todo. Several words are joined with single spaces. |
| `list` | Shows every todo in id order: id, `[x]` (done) or `[ ]` (pending), and text, then a summary line. |
| `complete <id> [<id>...]` | Marks todos as done. Completing a todo that is already done prints a note and still succeeds. |
| `delete <id> [<id>...]` | Removes todos. |
| `help`, `--help`, `-h` | Prints usage. |

Results go to stdout. Errors go to stderr, with the correct usage line when the command line was wrong:

```console
$ node index.js complete abc
Error: Invalid todo id "abc": expected a positive whole number such as 1
Run "node index.js help" to see all commands.

$ node index.js delete 7
Error: No todo with id #7
Run "node index.js list" to see the ids in use.
```

### Exit codes

| Code | Meaning |
| --- | --- |
| 0 | Success, including `list` on an empty list and completing an already-completed todo. |
| 1 | The command was valid but could not be carried out: unknown id, item limit reached, unreadable or invalid `todos.json`, lock timeout. |
| 2 | Usage error: missing command or argument, malformed id, empty or over-long text, invalid configuration. |

### Configuration

All settings are optional environment variables. Blank values count as unset. Invalid values stop the command with exit code 2 and an error naming the variable.

| Variable | Default | Meaning |
| --- | --- | --- |
| `TODO_ID_STRATEGY` | keep the list's current strategy; `max` for a new list | How new ids are chosen: `max` or `sequence` (see below). |
| `TODO_MAX_TEXT_LENGTH` | `500` | Longest todo text accepted, in user-perceived characters. |
| `TODO_MAX_ITEMS` | `10000` | Most todos one list may hold. |
| `TODO_LOCK_TIMEOUT_MS` | `5000` | How long a command waits for another running command to finish with `todos.json`. |

## Storage format

With the default `max` strategy, `todos.json` is a plain array:

```json
[
  {
    "id": 1,
    "text": "Buy groceries",
    "completed": false,
    "createdAt": "2026-09-30T12:00:00.000Z"
  }
]
```

With the `sequence` strategy, the file also records the highest id ever assigned: `{ "lastId": 3, "todos": [ ... ] }`. Both layouts can always be read. When `TODO_ID_STRATEGY` is unset, a list keeps the layout, and so the strategy, it was saved with. Setting the variable explicitly converts the file on its next change.

A missing file, a zero-byte file, or a file holding only whitespace counts as an empty list. `list` never creates the file. Fields the app does not know about are kept when it rewrites a todo.

## Design decisions

### Module layout

| File | Responsibility |
| --- | --- |
| `index.js` | Entry point. Passes `process.argv` to `run()` and sets the exit code. |
| `src/cli.js` | Argument handling, command dispatch, help text, messages, and the mapping from errors to exit codes. |
| `src/todos.js` | Pure list operations: add, complete, delete, id parsing, text validation. No I/O and no clock. |
| `src/id-strategies.js` | The two id-assignment strategies. |
| `src/storage.js` | Reading, validating, and atomically writing `todos.json`. Read-modify-write runs under the lock. |
| `src/lock.js` | The lock file that serializes concurrent commands. |
| `src/config.js` | Parsing and validating environment variables. |
| `src/format.js` | `list` output and escaping for the terminal. |
| `src/errors.js` | `TodoError` / `UsageError`, error codes, and exit codes. |

`run()` takes its working directory, environment, output streams, and clock as parameters. Tests can therefore drive the whole CLI in-process against a temporary directory and a fixed time.

### Two ways to assign ids

The spec asks for "auto-incrementing" ids but does not say whether the id of a deleted todo may be given out again. Both readings are implemented:

- **`max` (default):** the next id is the highest id in the list plus one. This is how SQLite assigns a rowid by default. It needs no extra state, so `todos.json` is exactly the array of todos the spec describes. The catch is that deleting the newest todo frees its id: add #1 and #2, delete #2, and the next todo is #2 again.
- **`sequence`:** ids are never reused, like SQLite's `AUTOINCREMENT`. This needs the high-water mark (`lastId`) stored in the file, which changes the file from a bare array to an object.

`max` is the default for a new list because it keeps the storage format the spec describes. Once a list is saved with `sequence`, it stays on `sequence` until `TODO_ID_STRATEGY=max` is set explicitly. That way, a single run that forgot the variable cannot drop `lastId` and let an id be reused. Choose `sequence` if scripts or notes refer to todos by id and a reused id could point them at the wrong todo. Deleting `todos.json` resets either strategy to 1. Both strategies refuse to go past `Number.MAX_SAFE_INTEGER` instead of producing an inexact id.

### Protecting the data file

- **Invalid files are never overwritten.** If `todos.json` is not valid JSON, or a todo has a wrong or missing field or a duplicate id, every command stops with exit 1. The error names the file and the first problem, e.g. `item at index 1 has an invalid "completed"`. Writing an empty list over a file you could still fix by hand would lose data.
- **Writes are atomic.** A change is written to a temporary file in the same directory, flushed to disk, and then renamed over `todos.json`. A crash leaves either the old list or the new one. The file's permissions are kept, and a symlinked `todos.json` is written through, not replaced.
- **Concurrent commands do not lose changes.** Without coordination, two commands started together (for example from a script) can both read the list, and the second write discards the first. Commands that change the list take `todos.json.lock`, created with an exclusive open. Others wait, retrying with jitter, up to `TODO_LOCK_TIMEOUT_MS`. `list` doesn't take the lock, because atomic renames mean it always reads a complete file.
- **Abandoned locks are recovered.** A lock is taken over if the process that wrote it no longer exists on this host, or if the lock is more than 10 seconds old. Commands hold it for milliseconds. After a crash, several waiting commands can find the same abandoned lock at once. If each of them deleted whatever was at the lock path, a slower one could delete the fresh lock a faster one had just created. So the lock is checked again and deleted while holding a second, short-lived guard file (`todos.json.lock.takeover`) that only one waiter can own.
- **Ownership is checked on release.** Each lock carries a random token and is removed only by its owner. If a command finds its lock was taken over, it reports `LOCK_LOST` instead of success.

### Input handling

- Text is NFC-normalized and trimmed. Empty text, text with control characters (newlines, tabs, escape sequences), and text over the length limit are rejected. Length is counted in grapheme clusters, so `👨‍👩‍👧` counts as one character, not eight code units. A grapheme can carry any number of combining marks, so the text is also capped at 16 code points per allowed character. That keeps the limit a real bound on stored size.
- Ids must be ASCII digits forming a positive safe integer. `1e3`, `0x10`, `+1`, `1.5`, and `-1` are rejected instead of being coerced by `Number()`. Leading zeros are accepted (`007` is 7).
- With several ids, `complete` and `delete` either apply to all of them or to none. One unknown or malformed id rejects the whole command, and duplicates are collapsed.
- Everything printed is escaped: todo text and error messages that quote `todos.json` content or arguments show control characters (including C1 codes such as U+009B) as `\uXXXX`. A hand-edited or shared file therefore cannot send escape sequences to your terminal.

### Isolation and limits

Each directory has its own `todos.json` and lock, so lists in different directories never interact. Text length, item count, and lock wait have defaults and can be set per invocation through the environment.

## Development

```console
$ npm install        # dev dependencies (ESLint) only
$ npm test           # node:test, all files matching test/**/*.test.js
$ npm run lint
```

| Directory | What it covers |
| --- | --- |
| `test/unit/` | Pure modules: list operations, id strategies, formatting, configuration. |
| `test/integration/` | Storage and locking on a real filesystem, and the CLI run in-process across all modules. |
| `test/e2e/` | `node index.js` as a real child process, including several processes adding at once. |
| `test/edge-cases/` | Unicode, length and item limits, unusual ids, corrupt or unreadable files, crashed and held locks. |

Tests that touch the filesystem each get a fresh temporary directory. Permission tests are skipped when running as root, because root ignores file permissions.

