/**
 * Resolves ids to todos in argument order, dropping duplicates. Throws before
 * any change is made if an id is unknown, so multi-id commands are all-or-nothing.
 */
function findAll(todos, ids) {
  const byId = new Map(todos.map((todo) => [todo.id, todo]));
  const uniqueIds = [...new Set(ids)];
  const missing = uniqueIds.filter((id) => !byId.has(id));
