 * @param {TodoState} state
 * @param {readonly number[]} ids
 * @returns {{ state: TodoState, results: { todo: Todo, alreadyCompleted: boolean }[], changed: boolean }}
 * @throws {TodoError} NOT_FOUND when any id is unknown; nothing is completed in that case.
 */
export function completeTodos(state, ids) {
  const results = findAll(state.todos, ids).map((todo) =>
    todo.completed ? { todo, alreadyCompleted: true } : { todo: { ...todo, completed: true }, alreadyCompleted: false },
  );
