/** Status indicators shown by `list`. */
export const STATUS_MARKERS = Object.freeze({ done: '[x]', pending: '[ ]' });

/** Printed by `list` when there is nothing to show. */
export const EMPTY_LIST_MESSAGE = 'No todos yet.';

const CONTROL_CHARACTERS = /\p{Cc}/gu;
const UNICODE_ESCAPE_WIDTH = 4;

/**
 * Shows control characters as `\uXXXX`. The CLI rejects them on input, but a
 * hand-edited or shared todos.json could still carry escape sequences that
 * would otherwise be interpreted by the terminal.
 * @param {string} text
 */
export function sanitizeForTerminal(text) {
  return text.replace(
    CONTROL_CHARACTERS,
    (character) => `\\u${character.codePointAt(0).toString(16).padStart(UNICODE_ESCAPE_WIDTH, '0')}`,
  );
}

/**
 * One `list` line, e.g. `3. [x] Buy groceries`.
 * @param {import('./todos.js').Todo} todo
 * @param {number} [idWidth] Pad the id to this many columns so markers line up.
 */
export function formatTodoLine(todo, idWidth = String(todo.id).length) {
  const marker = todo.completed ? STATUS_MARKERS.done : STATUS_MARKERS.pending;
  return `${String(todo.id).padStart(idWidth)}. ${marker} ${sanitizeForTerminal(todo.text)}`;
}

/**
 * e.g. `3 todos: 2 pending, 1 done`.
 * @param {readonly import('./todos.js').Todo[]} todos
 */
export function formatSummary(todos) {
  const done = todos.filter((todo) => todo.completed).length;
  const noun = todos.length === 1 ? 'todo' : 'todos';
  return `${todos.length} ${noun}: ${todos.length - done} pending, ${done} done`;
}

/**
 * The full `list` output: todos in id order followed by a summary line.
 * @param {readonly import('./todos.js').Todo[]} todos
 */
export function formatTodoList(todos) {
  if (todos.length === 0) return EMPTY_LIST_MESSAGE;
  const sorted = todos.toSorted((a, b) => a.id - b.id);
  const idWidth = String(sorted.at(-1).id).length;
  return [...sorted.map((todo) => formatTodoLine(todo, idWidth)), '', formatSummary(todos)].join('\n');
}
