/**
 * Replaces the text of one todo. The id, completed flag, createdAt and any
 * unknown fields are kept.
 * @param {TodoState} state
 * @param {number} id
 * @param {string} rawText
 * @param {{ maxTextLength: number }} limits
 * @returns {{ state: TodoState, todo: Todo, changed: boolean }}
 * @throws {UsageError} INVALID_ARGUMENT when the text is invalid.
 * @throws {TodoError} NOT_FOUND when the id is unknown; nothing is changed in that case.
 */
export function editTodo(state, id, rawText, { maxTextLength }) {
  const text = normalizeTodoText(rawText, { maxTextLength });
  const [existing] = findAll(state.todos, [id]);
  if (existing.text === text) return { state, todo: existing, changed: false };
  const todo = { ...existing, text };
  const todos = state.todos.map((candidate) => (candidate === existing ? todo : candidate));
  return { state: { ...state, todos }, todo, changed: true };
}
'''
