async function listCommand(args, { filePath }) {
  const pendingOnly = args.length === 1 && args[0] === PENDING_FLAG;
  if (args.length > 0 && !pendingOnly) {
    throw new UsageError('"list" only accepts the option --pending', { usage: COMMANDS.list.usage });
  }
  const { todos } = await readTodoState(filePath);
  if (todos.length === 0) return `${EMPTY_LIST_MESSAGE} Add one with: ${PROGRAM_NAME} add "Buy groceries"`;
  if (!pendingOnly) return formatTodoList(todos);
  const pending = todos.filter((todo) => !todo.completed);
  return pending.length === 0 ? NO_PENDING_MESSAGE : formatTodoList(pending);
}

/** @param {string[]} args @param {CommandContext} context */
async function editCommand(args, { filePath, config }) {
  const [rawId, ...words] = args;
  if (rawId === undefined) throw new UsageError('Missing todo id', { usage: COMMANDS.edit.usage });
